-- ===============================================================================================
-- UNIVERSAL1 - start2_sql_code.sql: everything of the structure that is NOT a table. Run it SECOND, after start1_sql_tables.sql.
-- functions / RPC, triggers, row level security + policies, grants, views, realtime publication, pg_cron, the setup of the generic tables (kit8_setup_def_table), the data migrations / backfills of a
-- database that already exists - and NO seed rows (start3_sql_insert_missing.sql) and NO table definitions (start1_sql_tables.sql).
-- Order: 1. start1_sql_tables.sql   2. start2_sql_code.sql   3. start3_sql_insert_missing.sql.   Supabase -> SQL Editor -> paste a file -> Run. All of them are idempotent: safe to run twice.
-- The opposite is delete_sql_structure.sql (next to this file). Parts, in this order (the same numbers as in start1_sql_tables.sql):
--
--    1. create_tables.sql - base tables, personTable, contractTable, the PM project / task tables, kit8_setup_def_table, pm_touch_updated_at, pm_owns_project
--    2. update_currency_exchange_rate_types.sql - exchange rate TYPES (Default | Budget, as D365 FO): the key of a rate = day or day|Type
--    3. insert_currency_exchange_rates_2025_2026.sql - ECB exchange rates 2025 -> 2026 (Default: every working day, Budget: the planned rate of the year) for 9 currencies; generated by build_currency_rates_sql.js
--    4. create_product_tables.sql - product catalog + the shared descriptor / variant / price tables
--    5. create_resource_role_tables.sql - role types, roles, role rates, descriptors seniority / workLanguage / certification
--    6. create_management_genus_table.sql - management genus: costs (time / material / expense), revenue, payments
--    7. create_distribution_generic_table.sql - distribution types (front-loaded, back-loaded, uniform, normal, logarithmic, epidemic, manual) in 3 groups
--    8. create_budget_item_table.sql - budgetItemTable: budget items in folders (same shape as the management genus), each with an obligatory managementGenusItem
--    9. insert_rows_resource_table.sql - demo human / material / expense / revenue roles; managementGenus on the role types
--   10. create_person_type_table.sql - personTypeTable (Employee, Contractor) + 50 % Employee / 50 % Contractor of all persons
--   11. create_person_descriptors.sql - person Properties + Variants (separate certificate rows), a contract for every person
--   12. create_template_resource_contract_table.sql - templateResourceContractTable (rowOwnerGUID = management genus) + demo templates
--   13. create_pm_task_line_table.sql - task_line_table + RPC pm_set_task_last_edit_place (rowJSON.lastEditPlace)
--   14. create_management_calendar_tables.sql - management calendars (Project / Resource role / Person folders), their days, fill_management_calendar, the default Working days calendar
--   15. create_task_line_plan_table.sql - task_line_plan (the posted days of the task lines) + RPC create_task_line_plan (one transaction, Correct033) + the unpost trigger
--   16. create_user_calendar_tables.sql - user calendars, events, reminders
--   17. create_equipment_tables.sql - equipmentTypeTable + equipmentTable (the analog of the person for machines), equipment descriptors / variants, the role type "Equipment Resources", task_line_table.rowJSON.taskResourceKind
--   18. create_business_unit_tables.sql - cfrTypeTable (the enumeration of the Centers of Financial Responsibility) + businessUnitTable (a tree of any depth) + the checks of businessUnitAssigned
--   19. create_budget_scenario_table.sql - budgetScenarioTable (a plain list of budget scenarios, plan | fact) + the two seed scenarios
--   20. create_organization_scope.sql - userTable.rowJSON.userOrganization (obligatory) + organization_ensure_user + project_table.rowParentGUID (the organization, never changed) + organization invitations
--   21. create_resource_calendar.sql - the resource calendar = the capacity: hours per day on the management calendars, resourceCalendar on person / equipment / contract / template, the week modes, organization_resource_capacity
--   22. create_resource_busy_check.sql - resource_occupancy_x_movement (the abstract occupancy of the posted days) + organization_resource_busy_check + the check inside create_task_line_plan (resourceCapacityStrongMode) + planMovementStatus
--   23. create_calendar_lock.sql - the calendar lock: a change of a calendar that would put the capacity of a resource under its posted hours is refused (day rows, Fill, resourceCalendar pointers, contracts)
--   24. create_task_fact_input.sql - the fact input document of a task: task_fact_header + task_fact_usage_timeline (strong / free input by the project setting factStrongInputByTaskLine) + post / unpost
--   25. create_monitor01.sql - Monitor01: monitor01_view (incremental, pg_cron every 2 s, batches) + monitor01_dirty + task_line_fact_for_monitor01 + monitor01_sum_sources
--   26. create_vendor_invoice.sql - the legal entity catalog, the main vendor of partners / equipment / products, the VENDOR INVOICE document (one vendor + one contract) and its posting into the project status register
-- ===============================================================================================

DO $$
BEGIN
  IF to_regclass('public.project_table') IS NULL OR to_regclass('public."userTable"') IS NULL THEN
    RAISE EXCEPTION 'Run start1_sql_tables.sql first (the tables), then this file';
  END IF;
END $$;

-- ===============================================================================================
-- PART 1: create_tables.sql
-- base tables, personTable, contractTable, the PM project / task tables, kit8_setup_def_table, pm_touch_updated_at, pm_owns_project
-- ===============================================================================================



-- updated_at helpers (three names, all still referenced by older triggers)
CREATE OR REPLACE FUNCTION public.set_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW IS DISTINCT FROM OLD THEN
    NEW.updated_at := NOW();
  END IF;
  RETURN NEW;
END;
$$;


CREATE OR REPLACE FUNCTION public.kit8_touch_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  NEW."updated_at" := NOW();
  RETURN NEW;
END;
$$;


CREATE OR REPLACE FUNCTION public.pm_touch_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  NEW."updated_at" := NOW();
  RETURN NEW;
END;
$$;


-- uuid -> ltree label ('-' -> '_')
CREATE OR REPLACE FUNCTION public.pm_ltree_label(p_guid uuid) RETURNS ltree
LANGUAGE sql IMMUTABLE PARALLEL SAFE SET search_path = public, extensions AS $$
  SELECT text2ltree(replace(lower(p_guid::text), '-', '_'));
$$;


-- one helper for every catalog / generic table: RLS on + touch trigger + REPLICA IDENTITY FULL
CREATE OR REPLACE FUNCTION public.kit8_setup_def_table(p_table text) RETURNS void
LANGUAGE plpgsql AS $$
BEGIN
  EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', p_table);
  EXECUTE format('ALTER TABLE public.%I REPLICA IDENTITY FULL', p_table);
  EXECUTE format('DROP TRIGGER IF EXISTS set_updated_at_trigger ON public.%I', p_table);
  EXECUTE format('DROP TRIGGER IF EXISTS %I ON public.%I', 'trg_' || p_table || '_touch', p_table);
  EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.kit8_touch_updated_at()',
                 'trg_' || p_table || '_touch', p_table);
  EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON public.%I USING GIN ("rowJSON" jsonb_path_ops)', 'idx_' || p_table || '_rowJSON', p_table);
  EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON public.%I ("orderInList")', 'idx_' || p_table || '_order', p_table);
END;
$$;
DO $$
DECLARE
  t text;
  tables text[] := ARRAY[
    'googleDriveCommandTable', 'raciMemberTable', 'themeStoreTable',
    'mediaPostTable', 'mediaPostTableArchive',
    'userTable', 'userAuthTable', 'aiSessionTable',
    'dtcTaskFinishedTable', 'dtcCatalogExecutiveTable', 'dtcTaskRegisteredTable',
    'dtcTaskWaitingTable', 'dtcTaskProgressTable', 'dtcFreeExecutiveTable'
  ];
BEGIN
  FOREACH t IN ARRAY tables LOOP
    PERFORM public.kit8_setup_def_table(t);

    EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO anon, authenticated', t);
    EXECUTE format('DROP POLICY IF EXISTS "Allow anon select" ON public.%I', t);
    EXECUTE format('DROP POLICY IF EXISTS "Allow anon insert" ON public.%I', t);
    EXECUTE format('DROP POLICY IF EXISTS "Allow anon update" ON public.%I', t);
    EXECUTE format('DROP POLICY IF EXISTS "Allow anon sql_for_delete" ON public.%I', t);
    EXECUTE format('CREATE POLICY "Allow anon select" ON public.%I FOR SELECT TO anon, authenticated USING (true)', t);
    EXECUTE format('CREATE POLICY "Allow anon insert" ON public.%I FOR INSERT TO anon, authenticated WITH CHECK (true)', t);
    EXECUTE format('CREATE POLICY "Allow anon update" ON public.%I FOR UPDATE TO anon, authenticated USING (true) WITH CHECK (true)', t);
    EXECUTE format('CREATE POLICY "Allow anon sql_for_delete" ON public.%I FOR DELETE TO anon, authenticated USING (true)', t);
  END LOOP;
END $$;


-- ---- userTable: THE user record ---------------------------------------------------------
--   rowGUID      = the user's GUID in the whole app (userState.userGUID, project "rowOwnerGUID", ...).
--                  Any GUID: users can be imported from other systems with the GUIDs they had there.
--                  (PM tables store owners as uuid, so a user who owns projects needs a uuid here.)
--   rowOwnerGUID = the user's email, lower case, UNIQUE (index above). This is the only link to
--                  Supabase auth: a signed-in session is matched to its userTable row by email.
--   rowJSON      = { userEmail, userGUID, firstName, secondName, ... }
-- Life cycle: 1) user signs in  2) the app makes sure the userTable row of that email exists
--             3) userTable.rowGUID -> userState.userGUID -> project.rowOwnerGUID
-- Access (replaces the open policies of the loop above - whoever could edit this table could
-- make himself another user): a signed-in user reads / creates only the row of his own email
-- and may change only rowJSON / orderInList. GUIDs and emails are changed (and users are
-- imported) in the SQL editor or with the service key only.
REVOKE ALL ON public."userTable" FROM anon, authenticated;

GRANT SELECT, INSERT ON public."userTable" TO authenticated;

GRANT UPDATE ("rowJSON", "orderInList") ON public."userTable" TO authenticated;

DROP POLICY IF EXISTS "Allow anon select" ON public."userTable";

DROP POLICY IF EXISTS "Allow anon insert" ON public."userTable";

DROP POLICY IF EXISTS "Allow anon update" ON public."userTable";

DROP POLICY IF EXISTS "Allow anon delete" ON public."userTable";

DROP POLICY IF EXISTS "userTable_select_own" ON public."userTable";

DROP POLICY IF EXISTS "userTable_insert_own" ON public."userTable";

DROP POLICY IF EXISTS "userTable_update_own" ON public."userTable";

CREATE POLICY "userTable_select_own" ON public."userTable" FOR SELECT TO authenticated
  USING ("rowOwnerGUID" = lower(auth.jwt()->>'email'));

CREATE POLICY "userTable_insert_own" ON public."userTable" FOR INSERT TO authenticated
  WITH CHECK ("rowOwnerGUID" = lower(auth.jwt()->>'email'));

CREATE POLICY "userTable_update_own" ON public."userTable" FOR UPDATE TO authenticated
  USING ("rowOwnerGUID" = lower(auth.jwt()->>'email'))
  WITH CHECK ("rowOwnerGUID" = lower(auth.jwt()->>'email'));


-- The GUID of the signed-in user = userTable.rowGUID of the session's email.
-- No row yet (first seconds of a first sign-in) or a GUID that is not a uuid -> the Supabase
-- auth uid, which is also the GUID the app gives a new user. No session -> NULL.
CREATE OR REPLACE FUNCTION public.app_user_guid() RETURNS uuid
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE
  v_email text := lower(nullif(auth.jwt()->>'email', ''));
  v_guid  text;
BEGIN
  IF auth.uid() IS NULL THEN RETURN NULL; END IF;
  IF v_email IS NOT NULL THEN
    SELECT "rowGUID" INTO v_guid FROM public."userTable" WHERE "rowOwnerGUID" = v_email;
    IF v_guid ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RETURN v_guid::uuid;
    END IF;
  END IF;
  RETURN auth.uid();
END;
$$;

REVOKE ALL ON FUNCTION public.app_user_guid() FROM PUBLIC;

GRANT EXECUTE ON FUNCTION public.app_user_guid() TO anon, authenticated;

