-- GENERATED by kit8/sql/tools/build_currency_rates_sql.js on 2026-10-09 from the Frankfurter API (ECB reference rates, base EUR) - run the script again to refresh it.
-- (run AFTER done/create_tables.sql (currencyTable, currencyExchangeRateTable) and update_currency_exchange_rate_types.sql; IDEMPOTENT: ON CONFLICT DO NOTHING)
--
--   Default rates: 4086 rows = 9 currencies x the ECB working days 2024-12-31 .. 2026-10-09.
--                  currencyRatio = units of the currency for 1 EUR; a rate applies until the next one (weekends / holidays: the last working day).
--   Budget rates:  18 rows = one PLANNED rate per currency per year, dated 1 January = the rate of the first working day of that year (a budget does not
--                  follow the daily rate). rowParentGUID = 'YYYY-MM-DD|Budget', rowJSON.rateType = 'Budget'.
--   The currency is found by its ISO code, so the script works with any rowGUID of currencyTable. A code that is not in currencyTable is skipped.
