  USING (public.pm_owns_project("rowProjectGUID"));


DO $$
DECLARE
  v_all boolean;
BEGIN
  SELECT puballtables INTO v_all FROM pg_publication WHERE pubname = 'supabase_realtime';
  IF NOT FOUND THEN
    RAISE NOTICE 'publication supabase_realtime does not exist - realtime auto refresh is off';
  ELSIF NOT v_all AND NOT EXISTS (SELECT 1 FROM pg_publication_tables
                                   WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = 'task_line_plan_timeline') THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.task_line_plan_timeline;
  END IF;
END $$;


-- days posted before this table existed: one row per line and day (the movements are already one per line and day, each at the start of its day)
INSERT INTO public.task_line_plan_timeline ("rowProjectGUID", "rowOwnerGUID", "rowPeriodDatetime", "taskLineGUID", "qtyForBudget", "sumForContract", "sumForBudget", "sumForAccounting")
SELECT m."rowProjectGUID", m."rowOwnerGUID", m."rowPeriodDatetime", m."rowParentGUID", SUM(m."qtyTaskLine"), SUM(m."sumForContract"), SUM(m."sumForBudget"), SUM(m."sumForAccounting")
  FROM public.task_line_plan_movements m
 GROUP BY m."rowProjectGUID", m."rowOwnerGUID", m."rowParentGUID", m."rowPeriodDatetime"
ON CONFLICT ("taskLineGUID", "rowPeriodDatetime") DO NOTHING;


-- -------------------------------------------------------------------------------------
-- RPC create_task_line_plan("taskLinePlanJSON") - ONE transaction: replaces the posted days of a task.
--
--   { "taskGUID": "<uuid>",
--     "timeZone": "UTC",                                  -- optional: the zone the day starts in (default UTC)
--     "lines": [ { "lineGUID": "<uuid>", "baseOfDistribution": 1,
--                  "qtyTaskLine": 10, "sumForBudget": 100, "sumForContract": 100, "sumForAccounting": 100,       -- the totals of the line (null = none)
--                  "days": [ { "d": "2026-10-12", "c": 0.3333333333 }, ... ] } ] }       -- the days and their coefficients
--
-- Steps: lock the task and check the owner -> validate -> delete the earlier rows of the task -> insert round(total * c, 2) per day ->
-- Correct033 (last row) for the coefficients and the three amounts -> verify the totals -> taskIsPosted = true + baseOfDistribution on the lines.
-- Any error rolls EVERYTHING back. SECURITY DEFINER because the app has no write policy on task_line_plan; the owner of the project is checked first.
-- Returns { "lines": n, "rows": n }.
-- -------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.create_task_line_plan("taskLinePlanJSON" jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE
  v_task     uuid;
  v_project  uuid;
  v_tz       text;
  v_line     jsonb;
  v_guid     uuid;
  v_ids      uuid[] := ARRAY[]::uuid[];
  v_days     jsonb;
  v_n        integer;
  v_base     numeric;
  v_csum     numeric;
  v_last     uuid;
  v_genus    text;
  v_item     jsonb;
  v_ljson    jsonb;
  v_unit     text;
  v_kind     text;
  v_col      text;
  v_total    numeric;
  v_sum      numeric;
  v_diff     numeric;
  v_rows     integer := 0;
  v_idx      integer := 0;
  v_org      text;
  v_mode     text;
  v_check    boolean;
  v_busy     jsonb := '[]'::jsonb;
  v_busy_lines uuid[] := ARRAY[]::uuid[];
  r          record;
BEGIN
  IF "taskLinePlanJSON" IS NULL OR jsonb_typeof("taskLinePlanJSON") <> 'object' THEN
    RAISE EXCEPTION 'create_task_line_plan: taskLinePlanJSON must be an object';
  END IF;
  v_task := ("taskLinePlanJSON"->>'taskGUID')::uuid;
  v_tz   := COALESCE(NULLIF("taskLinePlanJSON"->>'timeZone', ''), 'UTC');

  -- lock the task (two Post presses cannot interleave) and check the owner
  SELECT t."projectGUID" INTO v_project FROM public.project_task_table t WHERE t."rowGUID" = v_task FOR UPDATE;
  IF v_project IS NULL OR NOT public.pm_owns_project(v_project) THEN
    RAISE EXCEPTION 'create_task_line_plan: task % does not exist or is not yours', v_task USING ERRCODE = '42501';
  END IF;
  IF jsonb_typeof("taskLinePlanJSON"->'lines') <> 'array' THEN
    RAISE EXCEPTION 'create_task_line_plan: "lines" must be an array';
  END IF;

  -- the capacity check (PART 22): the mode of the ORGANIZATION of the project. capacityModeOff (the default, also a project without an organization) = exactly as before.
  SELECT p."rowParentGUID", COALESCE(NULLIF(o."rowJSON"->>'resourceCapacityStrongMode', ''), 'capacityModeOff')
    INTO v_org, v_mode
    FROM public.project_table p LEFT JOIN public."organizationTable" o ON o."rowGUID" = p."rowParentGUID" WHERE p."rowGUID" = v_project;
  v_mode  := COALESCE(v_mode, 'capacityModeOff');
  v_check := v_mode <> 'capacityModeOff' AND v_org IS NOT NULL;
  IF v_check THEN
    -- the calendars of the resources, SHARED (a change of one of these calendars waits for this Post), then one lock per resource, both in sorted order (no deadlock)
    FOR r IN SELECT DISTINCT cal FROM (SELECT DISTINCT COALESCE(NULLIF(l."rowJSON"->>'taskResourceKind', ''), 'person') AS k, l."rowJSON"->>'taskResourceItem' AS g
                                         FROM public.task_line_table l
                                        WHERE l."rowOwnerGUID" = v_task AND l."rowParentGUID" = 'timeGenus' AND COALESCE(l."rowJSON"->>'taskResourceItem', '') <> '') x,
                                      LATERAL public.organization_resource_calendars(x.k, x.g) AS cal
              ORDER BY 1 LOOP
      PERFORM public.organization_lock_calendar(r.cal, true);
    END LOOP;
    -- one lock per resource of the Time lines, in sorted order (no deadlock): a second Post or a change of a calendar of the same resource waits until this one is committed
    FOR r IN SELECT DISTINCT COALESCE(NULLIF(l."rowJSON"->>'taskResourceKind', ''), 'person') AS k, l."rowJSON"->>'taskResourceItem' AS g
               FROM public.task_line_table l
              WHERE l."rowOwnerGUID" = v_task AND l."rowParentGUID" = 'timeGenus' AND COALESCE(l."rowJSON"->>'taskResourceItem', '') <> ''
              ORDER BY 1, 2 LOOP
      PERFORM public.organization_lock_resource(r.k, r.g);
    END LOOP;
  END IF;

  -- the earlier days of the task are replaced
  DELETE FROM public.task_line_plan_movements WHERE "rowOwnerGUID" = v_task;
  DELETE FROM public.task_line_plan_timeline WHERE "rowOwnerGUID" = v_task;

  FOR v_line IN SELECT value FROM jsonb_array_elements("taskLinePlanJSON"->'lines') LOOP
    v_guid := (v_line->>'lineGUID')::uuid;
    v_idx  := v_idx + 1;
    SELECT l."rowParentGUID", jsonb_build_object('budgetItemTaskLine', l."rowJSON"->'budgetItemTaskLine', 'taskManagementGenusLine', l."rowParentGUID",
                                                 'taskResourceKind', COALESCE(l."rowJSON"->'taskResourceKind', 'null'::jsonb)), l."rowJSON"
      INTO v_genus, v_item, v_ljson
      FROM public.task_line_table l WHERE l."rowGUID" = v_guid AND l."rowOwnerGUID" = v_task;
    IF v_genus IS NULL THEN
      RAISE EXCEPTION 'create_task_line_plan: line % is not a line of task %', v_guid, v_task;
    END IF;

    -- the business unit of the line (PART 18): its kind = the folder of the genus of the budget item (costsGenus -> 'cost', revenuesGenus -> 'revenue'),
    -- else of the genus of the line. A line without a unit is posted as before. A cost on a revenue center (or a revenue on a cost center) is REFUSED.
    v_unit := NULLIF(v_ljson->>'businessUnitTaskLine', '');
    SELECT CASE gf."rowGUID" WHEN 'costsGenus' THEN 'cost' WHEN 'revenuesGenus' THEN 'revenue' END INTO v_kind
      FROM public."budgetItemTable" bi
      JOIN public."managementGenusTable" g  ON g."rowGUID"  = bi."rowJSON"->>'managementGenusItem'
      JOIN public."managementGenusTable" gf ON gf."rowGUID" = g."rowParentGUID"
     WHERE bi."rowGUID" = v_ljson->>'budgetItemTaskLine';
    IF v_kind IS NULL THEN
      SELECT CASE gf."rowGUID" WHEN 'costsGenus' THEN 'cost' WHEN 'revenuesGenus' THEN 'revenue' END INTO v_kind
        FROM public."managementGenusTable" g JOIN public."managementGenusTable" gf ON gf."rowGUID" = g."rowParentGUID" WHERE g."rowGUID" = v_genus;
    END IF;
    IF v_unit IS NOT NULL THEN
      IF NOT EXISTS (SELECT 1 FROM public."businessUnitTable" b WHERE b."rowGUID" = v_unit) THEN
        RAISE EXCEPTION 'create_task_line_plan: line % has the business unit "%" that does not exist', v_guid, v_unit;
      END IF;
      IF NOT public.kit8_cfr_accepts(public.kit8_business_unit_cfr(v_unit), v_kind) THEN
        RAISE EXCEPTION 'create_task_line_plan: line % (a % line) cannot be posted to the business unit "%" - a %', v_guid, v_kind, v_unit,
                        COALESCE((SELECT c."rowJSON"->>'title' FROM public."cfrTypeTable" c WHERE c."rowGUID" = public.kit8_business_unit_cfr(v_unit)), 'unit without a CFR');
      END IF;
    END IF;
    v_item := v_item || jsonb_build_object('businessUnitAssigned', to_jsonb(v_unit), 'budgetKind', to_jsonb(v_kind));

    v_days := v_line->'days';
    IF jsonb_typeof(v_days) <> 'array' OR jsonb_array_length(v_days) = 0 THEN
      RAISE EXCEPTION 'create_task_line_plan: line % has no days', v_guid;
    END IF;
    v_n    := jsonb_array_length(v_days);
    v_base := COALESCE((v_line->>'baseOfDistribution')::numeric, 1);
    IF v_base <= 0 THEN RAISE EXCEPTION 'create_task_line_plan: baseOfDistribution of line % must be > 0', v_guid; END IF;

    SELECT COALESCE(SUM(round((e.value->>'c')::numeric, 10)), 0) INTO v_csum FROM jsonb_array_elements(v_days) e;
    IF abs(v_csum - v_base) > 0.000001 THEN
      RAISE EXCEPTION 'create_task_line_plan: the coefficients of line % add up to %, not to %', v_guid, v_csum, v_base;
    END IF;
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_days) e WHERE (e.value->>'c')::numeric < 0) THEN
      RAISE EXCEPTION 'create_task_line_plan: a coefficient of line % is negative', v_guid;
    END IF;

    -- one row per day: coefficient rounded to 10 digits, amounts = round(total * coefficient, 2) (null total = null amount)
    INSERT INTO public.task_line_plan_movements ("rowProjectGUID", "rowOwnerGUID", "rowParentGUID", "orderInList", "rowPeriodDatetime", "rowCoefficient",
                                       "qtyTaskLine", "sumForBudget", "sumForContract", "sumForAccounting", "rowJSON", "planMovementStatus", "periodDay")
    SELECT v_project, v_task, v_guid, v_idx * 100000 + e.ord,
           ((e.value->>'d')::date)::timestamp AT TIME ZONE v_tz,
           round((e.value->>'c')::numeric, 10),
           CASE WHEN jsonb_typeof(v_line->'qtyTaskLine')       = 'number' THEN round((v_line->>'qtyTaskLine')::numeric       * round((e.value->>'c')::numeric, 10), 2) END,
           CASE WHEN jsonb_typeof(v_line->'sumForBudget')      = 'number' THEN round((v_line->>'sumForBudget')::numeric      * round((e.value->>'c')::numeric, 10), 2) END,
           CASE WHEN jsonb_typeof(v_line->'sumForContract')    = 'number' THEN round((v_line->>'sumForContract')::numeric    * round((e.value->>'c')::numeric, 10), 2) END,
           CASE WHEN jsonb_typeof(v_line->'sumForAccounting')  = 'number' THEN round((v_line->>'sumForAccounting')::numeric  * round((e.value->>'c')::numeric, 10), 2) END,
           v_item,
           -- false = waits for the capacity check (only a Time line with a resource); every other row is active at once
           NOT (v_check AND v_genus = 'timeGenus' AND COALESCE(v_ljson->>'taskResourceItem', '') <> ''),
           (e.value->>'d')::date
      FROM jsonb_array_elements(v_days) WITH ORDINALITY AS e(value, ord);
    v_rows := v_rows + v_n;

    -- ---- Correct033: the last row of the distribution = the last day with a non-zero coefficient (else the last day) ----
    SELECT p."rowGUID" INTO v_last FROM public.task_line_plan_movements p
     WHERE p."rowParentGUID" = v_guid ORDER BY (p."rowCoefficient" > 0) DESC, p."rowPeriodDatetime" DESC LIMIT 1;

    SELECT v_base - COALESCE(SUM("rowCoefficient"), 0) INTO v_diff FROM public.task_line_plan_movements WHERE "rowParentGUID" = v_guid;
    IF v_diff <> 0 THEN
      UPDATE public.task_line_plan_movements SET "rowCoefficient" = "rowCoefficient" + v_diff WHERE "rowGUID" = v_last;
    END IF;

    FOREACH v_col IN ARRAY ARRAY['qtyTaskLine', 'sumForBudget', 'sumForContract', 'sumForAccounting'] LOOP
      IF jsonb_typeof(v_line->v_col) <> 'number' THEN CONTINUE; END IF;
      v_total := round((v_line->>v_col)::numeric, 2);
      EXECUTE format('SELECT COALESCE(SUM(%I), 0) FROM public.task_line_plan_movements WHERE "rowParentGUID" = $1', v_col) INTO v_sum USING v_guid;
      v_diff := v_total - v_sum;
      -- the rounding of n rows cannot lose more than n * 0.005: more is a bug, not a rounding
      IF abs(v_diff) > v_n * 0.005 + 0.000001 THEN
        RAISE EXCEPTION 'create_task_line_plan: % of line % differs by % after rounding (more than % rows can lose)', v_col, v_guid, v_diff, v_n;
      END IF;
      IF v_diff <> 0 THEN
        EXECUTE format('UPDATE public.task_line_plan_movements SET %I = %I + $1 WHERE "rowGUID" = $2', v_col, v_col) USING v_diff, v_last;
      END IF;
      -- verify
      EXECUTE format('SELECT COALESCE(SUM(%I), 0) FROM public.task_line_plan_movements WHERE "rowParentGUID" = $1', v_col) INTO v_sum USING v_guid;
      IF v_sum <> v_total THEN
        RAISE EXCEPTION 'create_task_line_plan: % of line % adds up to %, not to %', v_col, v_guid, v_sum, v_total;
      END IF;
    END LOOP;
    SELECT COALESCE(SUM("rowCoefficient"), 0) INTO v_sum FROM public.task_line_plan_movements WHERE "rowParentGUID" = v_guid;
    IF v_sum <> v_base THEN
      RAISE EXCEPTION 'create_task_line_plan: the coefficients of line % add up to %, not to %', v_guid, v_sum, v_base;
    END IF;

    v_ids := v_ids || v_guid;
  END LOOP;

  -- the capacity check (after Correct033, so it sees the final hours): every busy line is REPORTED. capacityModeBlock also deletes its rows and leaves it unposted ("Post needed");
  -- capacityModeWarn keeps them. A conflict is an answer, not an exception: an exception would roll the deletion back too.
  IF v_check THEN
    FOR r IN SELECT * FROM public.organization_resource_busy_check(v_task, v_org) LOOP
      v_busy := v_busy || jsonb_build_array(r.conflict);
      v_busy_lines := v_busy_lines || r.line_guids;
    END LOOP;
    IF v_mode = 'capacityModeBlock' AND COALESCE(array_length(v_busy_lines, 1), 0) > 0 THEN
      DELETE FROM public.task_line_plan_movements WHERE "rowParentGUID" = ANY (v_busy_lines);
      v_ids := ARRAY(SELECT x FROM unnest(v_ids) AS x WHERE NOT (x = ANY (v_busy_lines)));
    END IF;
    UPDATE public.task_line_plan_movements SET "planMovementStatus" = true WHERE "rowOwnerGUID" = v_task AND NOT "planMovementStatus";
  END IF;

  -- the timeline: the movements of the task grouped by line and DAY (the start of the day in the zone of the post)
  INSERT INTO public.task_line_plan_timeline ("rowProjectGUID", "rowOwnerGUID", "rowPeriodDatetime", "taskLineGUID", "qtyForBudget", "sumForContract", "sumForBudget", "sumForAccounting")
  SELECT m."rowProjectGUID", m."rowOwnerGUID", date_trunc('day', m."rowPeriodDatetime" AT TIME ZONE v_tz) AT TIME ZONE v_tz, m."rowParentGUID",
         SUM(m."qtyTaskLine"), SUM(m."sumForContract"), SUM(m."sumForBudget"), SUM(m."sumForAccounting")
    FROM public.task_line_plan_movements m
   WHERE m."rowOwnerGUID" = v_task
   GROUP BY m."rowProjectGUID", m."rowOwnerGUID", m."rowParentGUID", date_trunc('day', m."rowPeriodDatetime" AT TIME ZONE v_tz) AT TIME ZONE v_tz;

  -- posted lines: taskIsPosted + the base (a merge, no other key of the line is lost)
  UPDATE public.task_line_table l
     SET "rowJSON" = l."rowJSON" || jsonb_build_object('taskIsPosted', true, 'baseOfDistribution',
           COALESCE((SELECT (x.value->>'baseOfDistribution')::numeric FROM jsonb_array_elements("taskLinePlanJSON"->'lines') x WHERE (x.value->>'lineGUID')::uuid = l."rowGUID"), 1))
   WHERE l."rowGUID" = ANY (v_ids);
  -- a line of the task that was not sent has no days any more (its budget item was cleared): it is not posted
  UPDATE public.task_line_table l
     SET "rowJSON" = (l."rowJSON" - 'baseOfDistribution') || '{"taskIsPosted": false}'::jsonb
   WHERE l."rowOwnerGUID" = v_task AND NOT (l."rowGUID" = ANY (v_ids)) AND jsonb_exists(l."rowJSON", 'baseOfDistribution');

  SELECT count(*) INTO v_rows FROM public.task_line_plan_movements WHERE "rowOwnerGUID" = v_task;
  RETURN jsonb_build_object('lines', COALESCE(array_length(v_ids, 1), 0), 'rows', v_rows, 'mode', v_mode, 'busy', v_busy);
END;
$$;

REVOKE ALL ON FUNCTION public.create_task_line_plan(jsonb) FROM PUBLIC, anon;

GRANT EXECUTE ON FUNCTION public.create_task_line_plan(jsonb) TO authenticated;


-- -------------------------------------------------------------------------------------
-- The start or the finish DAY of a task changed (the scheduler writes rowJSON.startAt and rowDuration): its posted lines need a new post.
-- A write of the same days (the scheduler runs often) changes nothing.
-- -------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.task_line_plan_unpost_on_dates() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
BEGIN
  IF (NEW."rowDuration")::date IS DISTINCT FROM (OLD."rowDuration")::date
     OR NULLIF(NEW."rowJSON"->>'startAt', '')::timestamptz::date IS DISTINCT FROM NULLIF(OLD."rowJSON"->>'startAt', '')::timestamptz::date THEN
    UPDATE public.task_line_table l
       SET "rowJSON" = l."rowJSON" || '{"taskIsPosted": false}'::jsonb
     WHERE l."rowOwnerGUID" = NEW."rowGUID" AND l."rowJSON" @> '{"taskIsPosted": true}'::jsonb;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_task_line_plan_unpost_on_dates ON public.project_task_table;

CREATE TRIGGER trg_task_line_plan_unpost_on_dates
  AFTER UPDATE OF "rowJSON", "rowDuration" ON public.project_task_table
  FOR EACH ROW EXECUTE FUNCTION public.task_line_plan_unpost_on_dates();


NOTIFY pgrst, 'reload schema';
-- ===============================================================================================
-- PART 16: create_user_calendar_tables.sql
-- user calendars, events, reminders
-- ===============================================================================================



-- ---- updated_at trigger, RLS (every row belongs to app_user_guid()), grants -----------------
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['user_calendar_table', 'user_calendar_event_table', 'user_calendar_invitation_table'] LOOP
    PERFORM public.kit8_setup_def_table(t);
    EXECUTE format('REVOKE ALL ON public.%I FROM anon, authenticated', t);
    EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', t);
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', t || '_select', t);
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', t || '_insert', t);
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', t || '_update', t);
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', t || '_delete', t);
    EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING ("rowOwnerGUID" = (SELECT public.app_user_guid()))', t || '_select', t);
    EXECUTE format('CREATE POLICY %I ON public.%I FOR INSERT TO authenticated WITH CHECK ("rowOwnerGUID" = (SELECT public.app_user_guid()))', t || '_insert', t);
    EXECUTE format('CREATE POLICY %I ON public.%I FOR UPDATE TO authenticated USING ("rowOwnerGUID" = (SELECT public.app_user_guid())) WITH CHECK ("rowOwnerGUID" = (SELECT public.app_user_guid()))', t || '_update', t);
    EXECUTE format('CREATE POLICY %I ON public.%I FOR DELETE TO authenticated USING ("rowOwnerGUID" = (SELECT public.app_user_guid()))', t || '_delete', t);
  END LOOP;
END $$;


-- =====================================================================================
-- Project tasks -> calendar (automatic create / update / sql_for_delete)
-- =====================================================================================
-- Calendar rowJSON of one project task. Day plans = all-day (the finish is exclusive, so the
-- last day is finish - 1 day); hour / minute / second plans = timed.
CREATE OR REPLACE FUNCTION public.user_calendar_project_task_json(p_task public.project_task_table)
RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path = public, extensions AS $$
DECLARE
  v_project public.project_table%ROWTYPE;
  v_start   timestamptz;
  v_finish  timestamptz;
  v_sub_day boolean;
BEGIN
  SELECT * INTO v_project FROM public.project_table WHERE "rowGUID" = p_task."projectGUID";
  v_start := COALESCE(
    NULLIF(p_task."rowJSON"->>'startAt', '')::timestamptz,
    NULLIF(p_task."rowJSON"->>'manualStartAt', '')::timestamptz,
    NULLIF(v_project."rowJSON"->>'projectStartAt', '')::timestamptz,
    date_trunc('day', NOW() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC');
  v_finish := COALESCE(p_task."rowDuration", v_start);
  IF v_finish < v_start THEN v_finish := v_start; END IF;
  v_sub_day := COALESCE((v_project."rowJSON"->>'planHour')::boolean, false)
            OR COALESCE((v_project."rowJSON"->>'planMinute')::boolean, false)
            OR COALESCE((v_project."rowJSON"->>'planSecond')::boolean, false);
  RETURN jsonb_build_object(
    'kind', 'projectTask',
    'title', COALESCE(NULLIF(p_task."rowJSON"->>'name', ''), 'Task'),
    'allDay', NOT v_sub_day,
    'startAt', to_char(v_start AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
    'endAt', to_char((CASE WHEN v_finish > v_start THEN v_finish ELSE v_start + (CASE WHEN v_sub_day THEN INTERVAL '1 hour' ELSE INTERVAL '1 day' END) END) AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
    'startDate', to_char(v_start AT TIME ZONE 'UTC', 'YYYY-MM-DD'),
    'endDate', to_char((CASE WHEN v_finish > v_start THEN v_finish - INTERVAL '1 second' ELSE v_start END) AT TIME ZONE 'UTC', 'YYYY-MM-DD'),
    'description', COALESCE(p_task."rowJSON"->>'notes', ''),
    'color', p_task."rowJSON"->>'taskColor',
    'rowKind', p_task."rowJSON"->>'rowKind',
    'rowProgress', p_task."rowProgress",
    'done', p_task."rowProgress" >= 100,
    'projectGUID', p_task."projectGUID",
    'projectTaskGUID', p_task."rowGUID",
    'projectTitle', COALESCE(v_project."rowJSON"->>'name', ''),
    'notifications', '[]'::jsonb
  );
END;
$$;


CREATE OR REPLACE FUNCTION public.user_calendar_project_task_sync() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE
  v_json jsonb;
BEGIN
  IF TG_OP = 'DELETE' THEN
    DELETE FROM public.user_calendar_event_table WHERE "rowJSON"->>'projectTaskGUID' = OLD."rowGUID"::text;
    RETURN OLD;
  END IF;
  -- stages are summary rows: only tasks and milestones are calendar entries
  IF COALESCE(NEW."rowJSON"->>'rowKind', 'task') NOT IN ('task', 'milestone') THEN
    DELETE FROM public.user_calendar_event_table WHERE "rowJSON"->>'projectTaskGUID' = NEW."rowGUID"::text;
    RETURN NEW;
  END IF;
  v_json := public.user_calendar_project_task_json(NEW);
  UPDATE public.user_calendar_event_table e
     -- keep what the user added in the calendar (reminders, guests, Google link ...); the task wins on its own fields
     SET "rowJSON" = e."rowJSON" || (v_json - 'notifications'),
         "rowOwnerGUID" = NEW."rowOwnerGUID",
         "orderInList" = EXTRACT(EPOCH FROM (v_json->>'startAt')::timestamptz) * 1000
   WHERE e."rowJSON"->>'projectTaskGUID' = NEW."rowGUID"::text
     AND (e."rowJSON" || (v_json - 'notifications')) IS DISTINCT FROM e."rowJSON";
  IF NOT EXISTS (SELECT 1 FROM public.user_calendar_event_table e WHERE e."rowJSON"->>'projectTaskGUID' = NEW."rowGUID"::text) THEN
    INSERT INTO public.user_calendar_event_table ("rowOwnerGUID", "rowParentGUID", "orderInList", "rowJSON")
    VALUES (NEW."rowOwnerGUID", 'empty', EXTRACT(EPOCH FROM (v_json->>'startAt')::timestamptz) * 1000, v_json)
    ON CONFLICT DO NOTHING;
  END IF;
  RETURN NEW;
END;
$$;


DROP TRIGGER IF EXISTS trg_project_task_zzz_user_calendar ON public.project_task_table;

CREATE TRIGGER trg_project_task_zzz_user_calendar
  AFTER INSERT OR UPDATE OR DELETE ON public.project_task_table
  FOR EACH ROW EXECUTE FUNCTION public.user_calendar_project_task_sync();


-- project renamed / planning units changed -> refresh the calendar rows of its tasks
CREATE OR REPLACE FUNCTION public.user_calendar_project_sync() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
BEGIN
  IF (NEW."rowJSON"->>'name') IS DISTINCT FROM (OLD."rowJSON"->>'name')
     OR (NEW."rowJSON"->>'planHour') IS DISTINCT FROM (OLD."rowJSON"->>'planHour')
     OR (NEW."rowJSON"->>'planMinute') IS DISTINCT FROM (OLD."rowJSON"->>'planMinute')
     OR (NEW."rowJSON"->>'planSecond') IS DISTINCT FROM (OLD."rowJSON"->>'planSecond') THEN
    UPDATE public.user_calendar_event_table e
       SET "rowJSON" = e."rowJSON" || (public.user_calendar_project_task_json(t) - 'notifications')
      FROM public.project_task_table t
     WHERE t."projectGUID" = NEW."rowGUID"
       AND e."rowJSON"->>'projectTaskGUID' = t."rowGUID"::text;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_project_table_zzz_user_calendar ON public.project_table;

CREATE TRIGGER trg_project_table_zzz_user_calendar
  AFTER UPDATE OF "rowJSON" ON public.project_table
  FOR EACH ROW EXECUTE FUNCTION public.user_calendar_project_sync();

